selector_to_html = {"a[href=\"server_tester/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">server_tester<a class=\"headerlink\" href=\"#module-mcp.tools.server_tester\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP server testing and validation tools.</p><p>This module provides tools for testing MCP server configurations, validating\nconnections, and ensuring servers are working correctly before use in production.</p>", "a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#key-components\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Key Components<a class=\"headerlink\" href=\"#key-components\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-mcp.tools\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">tools<a class=\"headerlink\" href=\"#module-mcp.tools\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Tools Package.</p><p>This package provides comprehensive tools for exploring, managing, and interacting\nwith Model Context Protocol (MCP) servers. These tools enable discovery of server\ncapabilities, resource inspection, and interactive management of MCP server lifecycles.</p>", "a[href=\"#ai-powered-tools\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">AI-Powered Tools<a class=\"headerlink\" href=\"#ai-powered-tools\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#management-tools\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Management Tools<a class=\"headerlink\" href=\"#management-tools\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#available-classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Available Classes<a class=\"headerlink\" href=\"#available-classes\" title=\"Link to this heading\">\u00b6</a></h2><h3>Inspection Tools<a class=\"headerlink\" href=\"#inspection-tools\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"server_selector/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">server_selector<a class=\"headerlink\" href=\"#module-mcp.tools.server_selector\" title=\"Link to this heading\">\u00b6</a></h1><p>Intelligent MCP server selection and filtering tools for AI agents.</p><p>This module provides sophisticated tools for filtering, selecting, and recommending\nMCP servers based on various criteria including prefixes, capabilities, task analysis,\nand performance metrics. Designed to help AI agents make intelligent decisions about\nwhich servers to use for specific tasks.</p>", "a[href=\"#command-line-interface\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Command Line Interface<a class=\"headerlink\" href=\"#command-line-interface\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#inspection-tools\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Inspection Tools<a class=\"headerlink\" href=\"#inspection-tools\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#interactive-server-management\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Interactive Server Management<a class=\"headerlink\" href=\"#interactive-server-management\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#usage-examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Usage Examples<a class=\"headerlink\" href=\"#usage-examples\" title=\"Link to this heading\">\u00b6</a></h2><h3>Server Resource Inspection<a class=\"headerlink\" href=\"#server-resource-inspection\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#server-testing-and-validation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Server Testing and Validation<a class=\"headerlink\" href=\"#server-testing-and-validation\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"ai_assistant/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">ai_assistant<a class=\"headerlink\" href=\"#module-mcp.tools.ai_assistant\" title=\"Link to this heading\">\u00b6</a></h1><p>AI-friendly MCP server selection and configuration assistant.</p><p>This module provides tools specifically designed for AI agents to automatically\nselect, configure, and use MCP servers based on task analysis and intelligent\nrecommendations. It minimizes the need for manual configuration while maximizing\nthe effectiveness of server selection.</p>", "a[href=\"#server-resource-inspection\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Server Resource Inspection<a class=\"headerlink\" href=\"#server-resource-inspection\" title=\"Link to this heading\">\u00b6</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link", "reference-external"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`div.content ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
